module top_module(
    input CLK,
    input RESET,
    input AS20,
    input DS20,
    input RW20,
    input [31:0] A,
    output [31:0] D_OUT,
    input [1:0] SIZ,
    output [1:0] DSACK,
    output RAMOE,
    output [1:0] RAS,
    output [3:0] CAS,
    inout [31:0] D
