        .s_axi_aclk(s_axi_aclk),
        .Q(Q),
        .out(out),
        .txfifo_empty(txfifo_empty)
    );

    // Clock generation (10ns period)
    initial begin
        s_axi_aclk = 0;
        forever #5 s_axi_aclk = ~s_axi_aclk;
    end

        task reset_dut;

        begin
            Rst0 = 1;
            E = 0;
            DIA = 0;
            D = 0;
            fifo_tx_en = 0;
            @(posedge s_axi_aclk);
            #1;
            Rst0 = 0;
            @(posedge s_axi_aclk);
            #1;
        end
        endtask
    task testcase001;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Initial Reset State", test_num);
            reset_dut();

            #1;


            check_outputs(4'h0, 1'b1, 1'b1);
        end
        endtask

    task testcase002;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Single Write/Read", test_num);
            reset_dut();


            D = 4'h5; E = 1; DIA = 1;
            @(posedge s_axi_aclk); #1;
            E = 0; DIA = 0;
            @(posedge s_axi_aclk); #1;


            fifo_tx_en = 1;
            @(posedge s_axi_aclk); #1;
            fifo_tx_en = 0;
            @(posedge s_axi_aclk); #1;


            #1;



            check_outputs(4'h5, 1'b1, 1'b1);
        end
