                @(posedge s_axi_aclk); #1;
            end
            E = 0; DIA = 0;
            @(posedge s_axi_aclk); #1;


            for (i = 0; i < 8; i = i + 1) begin
                fifo_tx_en = 1;
                @(posedge s_axi_aclk); #1;
