        begin
            if (expected_Q === (expected_Q ^ Q ^ expected_Q) &&
                expected_out === (expected_out ^ out ^ expected_out) &&
                expected_txfifo_empty === (expected_txfifo_empty ^ txfifo_empty ^ expected_txfifo_empty)) begin
