                $display("  Got:      Q=%h, out=%b, txfifo_empty=%b",
                         Q, out, txfifo_empty);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,D, DIA, E, Rst0, fifo_tx_en, s_axi_aclk, Q, out, txfifo_empty);
    end

endmodule

