module fsm_module (
        input clk,
        input reset,
        input signal,
        output reg out);parameter S0=0, S1=1, S2=2, S3=3;
	reg[1:0] state, next;

	always @(posedge clk)
		if (reset) state <= S0;
		else state <= next;

	always_comb begin
		case (state)
			S0: next = signal ? S1 : S0;
			S1: next = signal ? S2 : S1;
			S2: next = signal ? S3 : S2;
			S3: next = signal ? S0 : S3;
			default: next = 'x;
		endcase
	end

	assign out = (state == S0) || (state == S2);

endmodule

