module fsm (
  input in,
  input [2:0] state,
  output reg [2:0] next_state,
  output reg out);parameter S0=0, S1=1, S2=2, S3=3, S4=4, S5=5;

    always_comb begin
        case (state)
            S0: next_state = in ? S2 : S1;
            S1: next_state = in ? S3 : S4;
            S2: next_state = in ? S1 : S5;
            S3: next_state = in ? S5 : S0;
            S4: next_state = in ? S0 : S2;
            S5: next_state = in ? S4 : S3;
        endcase
    end

    assign out = (state==S0) || (state==S2) || (state==S4);

endmodule

