module top_module(
    input clk,
    input n_reset,
    input [15:0] din,
    output dout
);reg [4:0] pwmcounter;
    reg [4:0] pwmthreshold;
    reg [33:0] scaledin;
    reg [15:0] sigma;
    reg out;

    assign dout = out;

    always @(posedge clk, negedge n_reset)
    begin
        if (!n_reset)
        begin
            sigma <= 16'b00000100_00000000; // Maintain the same initialization
            pwmthreshold <= 5'b10000;
            pwmcounter <= 5'd0;
            scaledin <= 34'd0;
        end
        else
        begin
            pwmcounter <= pwmcounter + 1;

            if (pwmcounter == pwmthreshold)
                out <= 1'b0;

            if (pwmcounter == 5'b11111)
            begin
                scaledin <= (1 << (16 - 5)) << 16 + din * 61440; // Corrected shifted value
                sigma <= scaledin[31:16] + {5'b00000, sigma[10:0]}; // Corrected to 5'b00000
                pwmthreshold <= sigma[15:11];
                out <= 1'b1;
            end
            else
            begin
                out <= 1'b1;
            end
        end
    end

endmodule

