module top_module(clk, kld, out);input clk; 
 input kld; 
 output [31:0] out; 
 reg [31:0] out; 
 reg [3:0] rcnt; 
 wire [3:0] rcnt_next; 
 always @(posedge clk) 
  if(kld) out <= #1 32'h01_00_00_00; 
  else out <= #1 frcon(rcnt_next); 
 assign rcnt_next = rcnt + 4'h1; 
 always @(posedge clk) 
  if(kld) rcnt <= #1 4'h0; 
  else rcnt <= #1 rcnt_next; 
 function [31:0] frcon; 
 input [3:0] i; 
 case(i) 
  4'h0: frcon=32'h01_00_00_00; 
  4'h1: frcon=32'h02_00_00_00; 
  4'h2: frcon=32'h04_00_00_00; 
