                              (!A && !B && C) || (!B && !C && !D) ||
                              (!A && B && !C && D);

    assign segs[4] = (!A && C && !D) || (!B && !C && !D);

    assign segs[5] = (A && !B && !C) || (!A && B && !C) || 
                              (!B && !C && !D) || (!A && B && !D);

    assign segs[6] = (A && !B && !C) || (!A && !B && C) || 
                              (!A && B && !C) || (!A && C && !D);

endmodule

