module top_module (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter U=2'b00, V=2'b01, W=2'b10;

    always_comb begin
		case (state)
			U: next_state = in ? W : V;
			V: next_state = in ? U : W;
			W: next_state = in ? V : U;
		endcase
    end

    always_comb begin
		case (state)
			U: out = 1;
			V: out = 1;
			W: out = 0;
		endcase
    end

endmodule

