module top_module(
			inclk, 
			outclk, 
			reset_n);input inclk, reset_n;
	output outclk;

	reg [15:0] cnt;
	reg outclk;


	always @(posedge inclk, negedge reset_n)
	begin
		if (!reset_n)
			cnt <= 16'd0;
		else begin
			cnt <= {cnt[14:0], ~cnt[15]};
			outclk <= cnt[15];
		end
	end
endmodule

