module top_module(
  input data_in,
  input ref_clk,
  output reg clk_out,   // Changed from wire to reg
  output reg data_out   // Changed from wire to reg
);// Define PLL parameters
  parameter integer N = 10; // PLL divider
  parameter integer M = 100; // PLL multiplier
  parameter integer C = 10; // PLL loop filter coefficient

  // Define internal signals
  reg pll_clk;
  reg [N-1:0] pll_counter;
  reg [31:0] phase_accumulator;
  wire [31:0] phase_increment;
  wire [31:0] phase_error;
  wire [31:0] loop_filter_output;

  // Generate phase increment
  assign phase_increment = (ref_clk * M) / (1 << N);

  // Calculate phase error
  assign phase_error = phase_accumulator - (data_in * (1 << 31));

  // Calculate loop filter output
  assign loop_filter_output = phase_error * C;

  // Update phase accumulator
  always @(posedge pll_clk) begin
    phase_accumulator <= phase_accumulator + phase_increment + loop_filter_output;
  end

  // Generate recovered clock
  always @(posedge pll_clk) begin
    if (pll_counter == (N-1)) begin
      pll_counter <= 0;
      clk_out <= ~clk_out;
    end else begin
      pll_counter <= pll_counter + 1;
    end
  end

  // Generate recovered data
  always @(posedge clk_out) begin
    data_out <= data_in;
  end

  // Initialize internal signals
  initial begin
    pll_clk <= 0;
    pll_counter <= 0;
    phase_accumulator <= 0;
    clk_out <= 0;       // Initialize clk_out
    data_out <= 0;      // Initialize data_out
  end

  // Generate PLL clock
  always @(posedge ref_clk) begin
    pll_clk <= ~pll_clk;
  end

endmodule

